/* kult_port.h — ayudas del port que no son piezas del original.
 *
 * `cpu_delay`: sustituye los bucles `dbf` que solo consumen tiempo (reveal,
 * animacion, ...). En el diferencial es un no-op (lo que se compara es la
 * imagen, no el tiempo); el build nativo lo reemplaza para ceder frames.
 */
#ifndef KULT_PORT_H
#define KULT_PORT_H

#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

void wait_vbl(uint8_t *img);

/* KULT_FRAME_GATE: retardo (VBLs) por construccion de banco de frames. */
static inline void frame_gate_delay(uint8_t *img) {
    static int fg = -1;
    if (fg < 0) { const char *e = getenv("KULT_FRAME_GATE"); fg = e ? atoi(e) : 0; }
    for (int i = 0; i < fg; i++) wait_vbl(img);
}

static inline void cpu_delay(uint32_t units) { (void)units; }

/* Retardo de CPU por ciclos exactos (bucles que no son `dbf`). En el
 * diferencial es un no-op: solo cuenta el tiempo en el ejecutable. */
static inline void cpu_delay_cycles(uint64_t cycles) { (void)cycles; }

/* Logger de diagnostico del motor nativo: no-op en el diferencial. */
static inline FILE *kult_dbgfile(void) { return NULL; }

#endif

/* kult_api.h — API pública del core reconstruido (frontera con el motor).
 *
 * El core expone un conjunto reducido de símbolos (los que el motor nativo
 * necesita); el resto queda local vía el version-script `kult_core.map` al
 * construir `build/libkultcore.so` (`make core`). Así, al enlazar con SDL y
 * otras librerías no hay colisiones con los ~400 símbolos internos.
 *
 * El build diferencial (harness) NO usa el version-script: necesita ver todos
 * los símbolos por dlsym. La lista de exportados vive en `kult_core.map`; el
 * test `test/test_visibility.py` comprueba que solo se exporta esa lista.
 */
#ifndef KULT_API_H
#define KULT_API_H

#include <stdint.h>

#if defined(_WIN32)
#  define KULT_API __declspec(dllexport)
#elif defined(__GNUC__)
#  define KULT_API __attribute__((visibility("default")))
#else
#  define KULT_API
#endif

#ifdef __cplusplus
extern "C" {
#endif

KULT_API void copy_screen(uint8_t *img);
KULT_API void crt0_init(uint8_t *img);
KULT_API void cursor_draw(uint8_t *img);
KULT_API void cursor_restore(uint8_t *img);
