            Properties.Settings.Default.Save();
        }

        /// <summary>
        /// Constructor. Initilaise colour translation dictionary. 
        /// </summary>
        public CPCPalette()
        {
            PCColours.Add(0, new Tuple<int, Color>(0x54, Color.FromRgb(0x00, 0x00, 0x00)));    // 0 - Black
