            PCColours.Add(18, new Tuple<int, Color>(0x52, Color.FromRgb(0x00, 0xFF, 0x00)));    // 18 - Bright Green
            PCColours.Add(19, new Tuple<int, Color>(0x42, Color.FromRgb(0x00, 0xFF, 0x80)));    // 19 - Sea Green
