    Base64K = 0,
    ExtendedRAM = 1
};

struct Breakpoint {
    u16 address;
    BreakpointCode code;
    u16 condition;
};

struct WinApeBreakpoints {
    Breakpoint breakpoints[while(!std::mem::is_eof())];
};

// Structure globale d'un Chunk dynamique
struct Chunk {
    char name[4];
    u32 length;

    if (name == "CPC+") {
        CPCPlusData plus_data;
    } 
    else if (name == "BRKS") {
        WinApeBreakpoints breakpointsData;
    } 
    else if (name == "DSCA" || name == "DSCB") {
        char disk_path[length]; // Chaîne de caractères contenant le chemin du disque
    } 
    else if (name[0] == 'M' && name[1] == 'E' && name[2] == 'M') {
        // Blocs mémoire compressés (MEM0 à MEM8)
        u8 rle_compressed_ram[length];
    } 
    else {
        // Chunk inconnu ou générique, évite de casser le décodage des suivants
        u8 unknown_data[length];
    }
};

// Structure principale de l'entête SNA
struct SNAHeader {
    char magic[8]; // "MV - SNA"
    u8 reserved1[8];
    u8 version;

    // Registres Z80 principal
    u8 F;
    u8 A;
    u8 C;
    u8 B;
    u8 E;
    u8 D;
    u8 L;
    u8 H;
    u8 R;
    u8 I;
    u8 IFF0;
    u8 IFF1;
    u16 IX;
    u16 IY;
    u16 SP;
    u16 PC;
    u8 interrupt_mode;

    // Registres Z80 alternatifs
    u8 F_prime;
    u8 A_prime;
    u8 C_prime;
    u8 B_prime;
    u8 E_prime;
    u8 D_prime;
    u8 L_prime;
    u8 H_prime;

    // Matériel
    u8 ga_selected_pen;
    u8 ga_current_palette[17];
    u8 ga_multi_configuration;
    u8 current_ram_configuration;
    u8 crtc_selected_register;
    u8 crtc_register_data[18];
    u8 current_rom_selection;
    u8 ppi_port_a;
    u8 ppi_port_b;
    u8 ppi_port_c;
    u8 ppi_control_port;
    u8 psg_selected_register;
    u8 psg_register_data[16];

    u16 memory_dump_size_kb;

    // Données spécifiques aux versions
    if (version == 1) {
        u8 reserved2[93];
    } 
    else if (version == 2) {
        CPCType cpc_type;
        u8 interrupt_number;
        u8 multimode_bytes[6];
        u8 reserved2[85];
    } 
    else if (version == 3) {
        CPCType cpc_type;
        u8 interrupt_number;
        u8 multimode_bytes[6];
        u8 reserved2[39];

        u8 fdd_motor_drive_state;
        u8 fdd_current_physical_track[4];
        u8 printer_data_strobe_register;
        u8 reserved3[2];
        CRTCType crtc_type;
        u8 reserved4[4];
        u8 crtc_horizontal_character_counter;
        u8 unused_zero;
        u8 crtc_character_line_counter;
        u8 crtc_raster_line_counter;
        u8 crtc_vertical_total_adjust_counter;
        u8 crtc_horizontal_sync_width_counter;
        u8 crtc_vertical_sync_width_counter;
        u16 crtc_state_flags;
        u8 ga_vsync_delay_counter;
        u8 ga_interrupt_scanline_counter;
        u8 interrupt_request_flag;
        u8 reserved5[75];
    }
};

// Déclaration de l'entête à l'offset 0
SNAHeader header @ 0x00;

// Le dump mémoire non compressé (V2 style) commence à l'offset 0x100
// Si la mémoire est intégralement gérée par les chunks MEM, ce dump fait 0 octet
u8 memory_dump[header.memory_dump_size_kb * 1024] @ 0x100;

// Alignement automatique pour la lecture des Chunks V3 juste après la mémoire RAM
if (header.version == 3) {
    Chunk chunks[while(!std::mem::is_eof())] @ inline_addressof(memory_dump) + sizeof(memory_dump);
}

